export class EmailPasswordForm extends AccountHubStep {
  constructor() {
    super();
    XPCOMUtils.defineLazyPreferenceGetter(
      this,
      "rememberSignons",
      "signon.rememberSignons",
      true,
      (prefName, oldValue, newValue) => this.#setRememberPasswordInput(newValue)
    );
  }
